function log(table, id, action, field, oldValue, newValue, reason = '') {
  const definition = schema.sheets.find(s => s.name === table);
  const entity = state.tables[table].find(r => r[definition?.primaryKey] === id);
  const applicationId = table === 'Applications' ? id : entity?.application_id || '';
  state.tables.ActivityLog.push({ activity_id:newId('act'), occurred_at:nowISO(), actor:'recruiter-local', source:'ats_ui', entity_type:table, entity_id:id, job_id:table==='Jobs'?id:entity?.job_id || applicant(applicationId)?.job_id || '', application_id:applicationId, action, field_name:field, old_value_json:JSON.stringify(oldValue ?? null), new_value_json:JSON.stringify(newValue ?? null), reason, correlation_id:newId('op') });
  state.updated_at = nowISO();
}
function changeRow(table, key, id, changes, reason = '') {
  const row = state.tables[table].find(x => x[key] === id);
  if (!row) throw new Error('Không tìm thấy bản ghi.');
  for (const [field,val] of Object.entries(changes)) if (row[field] !== val) log(table,id,field.includes('status')?'status_change':'update',field,row[field],val,reason);
  Object.assign(row, changes, {updated_at:nowISO(), updated_by:'recruiter-local'}); return row;
}
function addRow(table, values) {
  const definition = schema.sheets.find(s => s.name === table);
  const row = Object.fromEntries((definition?.columns || []).map(c => [c.key, '']));
  Object.assign(row, values, {created_at:nowISO(),updated_at:nowISO(),updated_by:'recruiter-local'});
  state.tables[table].push(row); log(table,row[definition?.primaryKey],'create','',null,row); return row;
}
