function download(data,name,type='application/json') { const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000); }
function importData() {
  showModal({title:'Nhập dữ liệu theo schema',body:'<p>Chọn JSON xuất từ workspace này hoặc JSON có cấu trúc <code>{schema_version, tables: {Jobs: [], Candidates: [], …}}</code>.</p><label class="field">File JSON<input type="file" name="file" accept=".json,application/json" required /></label><p class="small muted">Dữ liệu được kiểm tra trước khi nhập. Nhập sẽ thay thế dữ liệu cục bộ; không ghi vào Google Sheet.</p>',submit:'Kiểm tra & nhập',async onSubmit(data){const file=data.get('file');if(!file?.size)throw new Error('Chọn file JSON.');if(file.size>10*1024*1024)throw new Error('File tối đa 10 MB để trình duyệt xử lý ổn định.');let parsed;try{parsed=JSON.parse(await file.text());}catch{throw new Error('File chưa phải JSON hợp lệ.');}const next=validateImport(parsed);state=next;state.mode='local';ui.recruitingDrafts={};ui.job='all';ui.drawer=null;ui.email=null;persist('Đã nhập dữ liệu vào workspace cục bộ.');}});
}

goalsFeature=createGoalsFeature({getWork:()=>workState,setWork:v=>{workState=v;},getUi:()=>ui,render,persist:persistWork,e,icon,header,button,field,select,dateLabel,showModal,toast,download});

function trackRecruitingDraft(form) {
  const key=`${form.dataset.applicationId}:${form.dataset.recruitingField}`;
  ui.recruitingDrafts[key]=Object.fromEntries(new FormData(form));
  form.classList.add('is-dirty');
  const error=form.querySelector('.inline-recruiting-error');error.textContent='';error.hidden=true;
}
function cancelRecruitingEdit(form) {
  const a=applicant(form.dataset.applicationId);if(!a)return;
  const values=recruitingValues(form.dataset.recruitingField,a,displayCandidate(state,a)||{});
  delete ui.recruitingDrafts[`${a.application_id}:${form.dataset.recruitingField}`];
  for(const [name,value] of Object.entries(values))form.elements.namedItem(name).value=value;
  form.classList.remove('is-dirty');
  const error=form.querySelector('.inline-recruiting-error');error.textContent='';error.hidden=true;
  form.querySelector('input,select,textarea')?.focus({preventScroll:true});
}
function saveRecruitingEdit(form) {
  const before=JSON.parse(JSON.stringify(state)),field=form.dataset.recruitingField,id=form.dataset.applicationId;
  const error=form.querySelector('.inline-recruiting-error');
  const draftKey=`${id}:${field}`,draft=ui.recruitingDrafts[draftKey];
  const scrollTop=$('.drawer-body')?.scrollTop||0;
  try {
    const a=applicant(id),c=a&&displayCandidate(state,a);
    if(!a||!c)throw new Error('Không tìm thấy hồ sơ ứng viên.');
    const {table,changes}=recruitingChanges(field,Object.fromEntries(new FormData(form)));
    const row=table==='Candidates'?c:a;
    if(Object.entries(changes).every(([key,value])=>row[key]===value)){cancelRecruitingEdit(form);return;}
    changeRow(table,table==='Candidates'?'candidate_id':'application_id',table==='Candidates'?c.candidate_id:id,changes);
    delete ui.recruitingDrafts[draftKey];
    persist('Đã lưu thông tin tuyển dụng.');
    const body=$('.drawer-body');if(body)body.scrollTop=scrollTop;
    const next=Array.from(document.querySelectorAll('[data-recruiting-field]')).find(el=>el.dataset.applicationId===id&&el.dataset.recruitingField===field);
    next?.querySelector('input,select,textarea')?.focus({preventScroll:true});
  }catch(err){
    state=before;if(draft)ui.recruitingDrafts[draftKey]=draft;
    error.textContent=err.message||'Không lưu được thay đổi.';error.hidden=false;
  }
}

function updateCandidateStage(control) {
  const id=control.dataset.applicationId,a=applicant(id),before=JSON.parse(JSON.stringify(state));
  if(!a)return;
  const stage=control.value,previousStage=a.stage,scrollTop=$('.drawer-body')?.scrollTop||0;
  try {
    const result=changeCandidateStage(state,id,stage);
    if(result.kind==='close'){control.value=previousStage;moveForm(id,'closed');return;}
    if(result.kind==='updated'){
      persist(result.reopened?'Đã mở lại hồ sơ.':'Đã cập nhật giai đoạn tuyển dụng.');
      const body=$('.drawer-body');if(body)body.scrollTop=scrollTop;
      $('.candidate-stage-select')?.focus({preventScroll:true});
    }
  }catch(err){state=before;control.value=previousStage;toast(err.message||'Chưa đổi được giai đoạn.');}
}

document.addEventListener('click', (event) => {
  const cancel=event.target.closest('[data-inline-cancel]');
  if(cancel){cancelRecruitingEdit(cancel.closest('[data-recruiting-field]'));return;}
  const target=event.target.closest('[data-action]');
  if(!target){const backdrop=event.target;if(backdrop.dataset.dismiss==='modal')closeModal();else if(backdrop.dataset.dismiss==='drawer'&&!ui.modal){ui.drawer=null;renderOverlay();refreshTodayGreeting();}return;}
  const {action,id,page,value,stage,app,feedback}=target.dataset;
  const before=JSON.parse(JSON.stringify(state)),beforeWork=JSON.parse(JSON.stringify(workState));
  if(target.tagName==='A')event.preventDefault();
  try {
    if(goalsFeature.handleAction(action,target.dataset))return;
    switch(action){
      case 'nav': ui.page=page;ui.search='';ui.menu=false;ui.drawer=null;if(page==='goals')ui.goalId=null;render();break;
      case 'menu':ui.menu=!ui.menu;render();break;
      case 'filter':ui.filter=value;render();break;
      case 'view':ui.view=value;render();break;
      case 'open-candidate':openCandidate(id);break;
      case 'close-drawer':ui.drawer=null;renderOverlay();refreshTodayGreeting();if(previousFocus?.isConnected)previousFocus.focus();break;
      case 'drawer-tab':ui.drawerTab=value;renderOverlay();break;
      case 'close-modal':closeModal();break;
      case 'add-job':jobForm();break;
      case 'edit-job':jobForm(id);break;
      case 'job-pipeline':ui.job=id;ui.page='pipeline';render();break;
      case 'add-candidate':candidateForm(null,stage);break;
      case 'edit-candidate':candidateForm(id);break;
      case 'assign-job':{const c=state.tables.Candidates.find(c=>c.candidate_id===id);if(!state.tables.Jobs.length){jobForm();break;}showModal({title:'Gắn ứng viên với vị trí',body:select('job_id','Vị trí',state.tables.Jobs.map(j=>[j.job_id,j.job_title]),'',true),onSubmit(data){const a=createCandidate(state,{...c,job_id:data.get('job_id')});ui.drawer=a.application_id;persist('Đã gắn ứng viên với vị trí.');}});break;}
      case 'move':moveForm(id);break;
      case 'application-status':moveForm(id);break;
      case 'add-task':taskForm(null,app);break;
      case 'task':taskForm(id);break;
      case 'complete-task':completeTask(state,id);persist('Đã hoàn tất công việc.');break;
      case 'undo-task':undoTaskCompletion(state,id);persist('Đã mở lại công việc.');break;
      case 'feedback':feedbackForm(id,feedback);break;
      case 'hm-form':feedbackForm(id,null,true);break;
      case 'request-feedback':requestFeedback(id);break;
      case 'add-round':roundForm(id);break;
      case 'round-edit':roundForm(null,id);break;
      case 'round-result':roundResult(id);break;
      case 'no-show':noShow(id);break;
      case 'documents':documentsModal(id);break;
      case 'candidate-email':emailForm(id);break;
      case 'new-email':emailForm();break;
      case 'select-email':ui.email=id;render();break;
      case 'email-attachments':attachmentsForm(id);break;
      case 'download-email':{const m=state.tables.Emails.find(x=>x.email_id===id);const form=$('#email-editor');const data=form?Object.fromEntries(new FormData(form)):m;download(`To: ${data.to_email}\nSubject: ${data.subject}\n\n${data.body}\n\nTài liệu tham chiếu (chưa đính kèm vào email):\n${json(m.attachment_document_ids_json).map(id=>{const d=state.tables.Documents.find(x=>x.document_id===id);return `${d?.file_name || id}: ${d?.file_url || 'Chưa có file'}`;}).join('\n')}`,'email-draft.txt','text/plain');toast('Đã tải bản nháp, chưa gửi email.');break;}
      case 'offer':offerForm(id);break;
      case 'data-table':ui.dataTable=value;render();break;
      case 'export':download(JSON.stringify(exportDatabase(state),null,2),`recruiting-database-${todayKey()}.json`);toast('Đã xuất đủ 10 bảng dữ liệu.');break;
      case 'export-csv':{const cols=schema.sheets.find(s=>s.name===ui.dataTable)?.columns.map(c=>c.key) || [];const csvValue=v=>{let s=typeof v==='object'&&v!==null?JSON.stringify(v):String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};download('\uFEFF'+[cols,...state.tables[ui.dataTable].map(r=>cols.map(c=>r[c]))].map(row=>row.map(csvValue).join(',')).join('\r\n'),ui.dataTable+'.csv','text/csv;charset=utf-8');break;}
      case 'import':importData();break;
      case 'reset-empty':confirmReset('local');break;
      case 'reset-demo':confirmReset('demo');break;
    }
  } catch(err){state=before;workState=beforeWork;toast(err.message || 'Chưa thực hiện được thao tác.');}
});
document.addEventListener('submit',async(event)=>{
  if(event.target.matches('[data-recruiting-field]')){
    event.preventDefault();saveRecruitingEdit(event.target);
  }else if(event.target.id==='modal-form'){
    event.preventDefault();const current=ui.modal;if(!current?.onSubmit)return;
    const before=JSON.parse(JSON.stringify(state)),beforeWork=JSON.parse(JSON.stringify(workState));const submit=event.target.querySelector('[type="submit"]');if(submit)submit.disabled=true;
    try{await current.onSubmit(new FormData(event.target));ui.modal=null;renderOverlay();}catch(err){state=before;workState=beforeWork;toast(err.message || 'Không lưu được thay đổi.');if(submit)submit.disabled=false;}
  }else if(event.target.id==='profile-name-form'){
    event.preventDefault();try{profileName=saveProfileName(new FormData(event.target).get('display_name'));render();toast('Đã lưu tên trong lời chào.');}catch(err){toast(err.message);}
  }else if(event.target.id==='email-editor'){
    event.preventDefault();const before=JSON.parse(JSON.stringify(state));try{const v=Object.fromEntries(new FormData(event.target)),original=state.tables.Emails.find(m=>m.email_id===v.email_id);if(v.subject===humanizeRoundText(original?.subject))v.subject=original.subject;if(v.body===humanizeRoundText(original?.body))v.body=original.body;updateEmailDraft(state,v.email_id,{to_email:v.to_email,subject:v.subject,body:v.body});persist('Đã lưu bản nháp; chưa gửi email.');}catch(err){state=before;toast(err.message);}
  }
});
document.addEventListener('change',event=>{const inline=event.target.closest('[data-recruiting-field]');if(inline){trackRecruitingDraft(inline);return;}if(event.target.dataset.change==='candidate-stage'){updateCandidateStage(event.target);return;}if(event.target.dataset.change==='job'){ui.job=event.target.value;render();}else if(event.target.dataset.change==='goal-category'){ui.goalCategory=event.target.value;render();}});
document.addEventListener('input',event=>{const inline=event.target.closest('[data-recruiting-field]');if(inline){trackRecruitingDraft(inline);return;}if(event.target.id==='goal-search'){const position=event.target.selectionStart;ui.goalSearch=event.target.value;render();const input=$('#goal-search');input?.focus();input?.setSelectionRange(position,position);}else if(event.target.id==='candidate-search'){const position=event.target.selectionStart;ui.search=event.target.value;render();const input=$('#candidate-search');input?.focus();input?.setSelectionRange(position,position);}});
document.addEventListener('dragstart',event=>{const card=event.target.closest('[data-drag]');if(card){event.dataTransfer.setData('text/plain',card.dataset.drag);event.dataTransfer.effectAllowed='move';card.classList.add('dragging');}});
document.addEventListener('dragend',()=>document.querySelectorAll('.dragging,.drag-over').forEach(el=>el.classList.remove('dragging','drag-over')));
document.addEventListener('dragover',event=>{const col=event.target.closest('.kanban-column');if(col){event.preventDefault();event.dataTransfer.dropEffect='move';document.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over'));col.classList.add('drag-over');}});
document.addEventListener('drop',event=>{const col=event.target.closest('.kanban-column');if(!col)return;event.preventDefault();const id=event.dataTransfer.getData('text/plain'),a=applicant(id);if(!a||a.stage===col.dataset.stage)return;try{if(col.dataset.stage==='closed'||a.application_status!=='active')moveForm(id,col.dataset.stage);else{moveApplication(state,id,col.dataset.stage,{status:'active',reason:'Recruiter kéo thả trên pipeline'});persist('Đã đổi giai đoạn; không gửi email.');}}catch(err){toast(err.message);}});
document.addEventListener('keydown',event=>{
  const inline=event.target.closest('[data-recruiting-field]');
  if(inline&&event.key==='Escape'){event.preventDefault();cancelRecruitingEdit(inline);return;}
  if(inline&&event.target.tagName==='TEXTAREA'&&event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();inline.requestSubmit();return;}
  if(event.key==='Escape'){if(ui.modal)closeModal();else if(ui.drawer){ui.drawer=null;renderOverlay();refreshTodayGreeting();}else if(ui.menu){ui.menu=false;render();}}
  if(event.key==='Tab'&&(ui.modal||ui.drawer)){const surface=ui.modal?$('.modal'):$('.drawer');const focusable=Array.from(surface?.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]):not([type="hidden"]),select,textarea,[tabindex="0"]') || []).filter(el=>el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
});
window.addEventListener('storage',event=>{if(event.key?.includes('recruit'))toast('Workspace thay đổi ở tab khác. Xuất dữ liệu hiện tại trước khi tải lại trang.');});
document.addEventListener('toggle',event=>{if(event.target.isConnected&&event.target.matches('.open-jobs-summary'))ui.openJobsExpanded=event.target.open;},true);
function refreshTodayGreeting() {
  if(ui.page!=='today')return;
  if(ui.todayRenderedDate!==todayKey()&&!ui.modal&&!ui.drawer){render();return;}
  const greeting=$('#today-greeting'),quote=$('#today-quote'),date=$('#today-date');
  if(greeting)greeting.textContent=getGreeting(new Date(),profileName);
  if(quote)quote.textContent='“'+getDailyQuote()+'”';
  if(date)date.textContent=new Intl.DateTimeFormat('vi-VN',{weekday:'long',day:'numeric',month:'long',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date());
}
setInterval(refreshTodayGreeting,60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshTodayGreeting();});
render();
